   189→      compatible,
   190→      message: compatible
   191→        ? `Assignment of '${argType}' to '${paramType}' is valid`
   192→        : `Cannot assign '${argType}' to '${paramType}' parameter '${paramName}'`,
   193→      details: {
   194→        expected: paramType,
   195→        received: argType,
