#!/usr/bin/env node

/**
 * FreeLang v2 Build System
 *
 * 사용법:
 *   npm run build:fl        (빌드 분석만)
 *   npm run build:ts        (TypeScript 컴파일만)
 *   npm run build           (빌드 분석 + 컴파일)
 *
 * 직접 실행:
 *   node build.js
 */

const fs = require('fs');
const path = require('path');

// ANSI 색상
const colors = {
  reset: '\x1b[0m',
  bright: '\x1b[1m',
  dim: '\x1b[2m',
  green: '\x1b[32m',
  blue: '\x1b[34m',
  yellow: '\x1b[33m',
  cyan: '\x1b[36m'
};

function log(msg, color = 'reset') {
  const c = colors[color] || colors.reset;
  console.log(`${c}${msg}${colors.reset}`);
}

function header(title) {
  log('═'.repeat(63), 'cyan');
  log(`  📦 ${title}`, 'bright');
  log('═'.repeat(63), 'cyan');
  log('');
}

function footer() {
  log('═'.repeat(63), 'cyan');
  log('  ✅ FreeLang Build Analysis Complete', 'green');
  log('═'.repeat(63), 'cyan');
  log('');
}

function phase(num, title) {
  log(`▶ Phase ${num}: ${title}`, 'blue');
}

