   956→  private valueToString(v: Value): string {
   957→    switch (v.tag) {
   958→      case "i32": case "f64": return String(v.val);
   959→      case "str": return v.val;
   960→      case "bool": return v.val ? "true" : "false";
   961→      case "void": return "void";
   962→      case "none": return "None";
   963→      case "arr": return `[${v.val.map((e) => this.valueToString(e)).join(", ")}]`;
   964→      case "struct": {
   965→        const entries = [...v.fields.entries()].map(([k, val]) => `${k}: ${this.valueToString(val)}`);
   966→        return `{ ${entries.join(", ")} }`;
   967→      }
   968→      case "ok": return `Ok(${this.valueToString(v.val)})`;
   969→      case "err": return `Err(${this.valueToString(v.val)})`;
   970→      case "some": return `Some(${this.valueToString(v.val)})`;
   971→      case "chan": return `channel(${v.id})`;
   972→    }
   973→  }
   974→
   975→  private valuesEqual(a: Value, b: Value): boolean {
   976→    if (a.tag !== b.tag) return false;
   977→    if (a.tag === "void" && b.tag === "void") return true;
   978→    if (a.tag === "none" && b.tag === "none") return true;
   979→    if ("val" in a && "val" in b) return (a as any).val === (b as any).val;
   980→    return false;
   981→  }
   982→
   983→  private deepClone(v: Value): Value {
   984→    switch (v.tag) {
   985→      case "arr": return { tag: "arr", val: v.val.map((e) => this.deepClone(e)) };
   986→      case "struct": {
   987→        const fields = new Map<string, Value>();
   988→        for (const [k, val] of v.fields) fields.set(k, this.deepClone(val));
   989→        return { tag: "struct", fields };
   990→      }
   991→      case "ok": return { tag: "ok", val: this.deepClone(v.val) };
   992→      case "err": return { tag: "err", val: this.deepClone(v.val) };
   993→      case "some": return { tag: "some", val: this.deepClone(v.val) };
