  private readI32(actor: Actor): number {
    const b0 = this.chunk.code[actor.ip++];
    const b1 = this.chunk.code[actor.ip++];
    const b2 = this.chunk.code[actor.ip++];
    const b3 = this.chunk.code[actor.ip++];
    return b0 | (b1 << 8) | (b2 << 16) | (b3 << 24);
