// FreeLang v4 — Bytecode Compiler (SPEC_02 구현)
// AST → Bytecode

import { Program, Stmt, Expr, Pattern, MatchArm, Param, TypeAnnotation } from "./ast";

// ============================================================
// Opcodes
// ============================================================

export enum Op {
  // 상수 로드
  PUSH_I32 = 0x01,
  PUSH_F64 = 0x02,
  PUSH_STR = 0x03,
  PUSH_TRUE = 0x04,
  PUSH_FALSE = 0x05,
  PUSH_VOID = 0x06,
  PUSH_NONE = 0x07,
  POP = 0x08,

  // 산술 (i32)
  ADD_I32 = 0x10,
  SUB_I32 = 0x11,
  MUL_I32 = 0x12,
  DIV_I32 = 0x13,
  MOD_I32 = 0x14,
  NEG_I32 = 0x15,

  // 산술 (f64)
  ADD_F64 = 0x18,
  SUB_F64 = 0x19,
  MUL_F64 = 0x1A,
  DIV_F64 = 0x1B,
  MOD_F64 = 0x1C,
  NEG_F64 = 0x1D,

  // 비교
  EQ = 0x20,
  NEQ = 0x21,
  LT = 0x22,
  GT = 0x23,
  LTEQ = 0x24,
  GTEQ = 0x25,

  // 논리
  AND = 0x28,
  OR = 0x29,
  NOT = 0x2A,

  // 문자열
  STR_CONCAT = 0x2E,

  // 변수
  LOAD_LOCAL = 0x30,
  STORE_LOCAL = 0x31,
  LOAD_GLOBAL = 0x32,
  STORE_GLOBAL = 0x33,

  // 제어
  JUMP = 0x40,
  JUMP_IF_FALSE = 0x41,
  RETURN = 0x42,
  HALT = 0x43,

  // 함수
  CALL = 0x50,
  CALL_BUILTIN = 0x51,

  // 배열
  ARRAY_NEW = 0x60,
  ARRAY_GET = 0x61,
  ARRAY_SET = 0x62,

  // 구조체
  STRUCT_NEW = 0x68,
  STRUCT_GET = 0x69,
  STRUCT_SET = 0x6A,

  // Option/Result
  WRAP_OK = 0x70,
  WRAP_ERR = 0x71,
  WRAP_SOME = 0x72,
  UNWRAP = 0x73,
  IS_OK = 0x74,
  IS_ERR = 0x75,
  IS_SOME = 0x76,
  IS_NONE = 0x77,

  // Actor/Channel
  SPAWN = 0x80,
  CHAN_NEW = 0x81,
  CHAN_SEND = 0x82,
  CHAN_RECV = 0x83,

  // 디버그
  DUP = 0xF0,
