  if (tok.type === TokenType.MINUS || tok.type === TokenType.NOT) {
    this.advance();
    const operand = this.parseExpr(BP_UNARY);
    return { kind: "unary", op: tok.lexeme, operand, line: tok.line, col: tok.col };
  }

