  // 클로저 메타데이터를 상수로 저장
  const closureIdx = this.chunk.addConstant({
    params: paramNames,
    // body bytecode는 나중에 런타임에서 해석됨
  });

  this.chunk.emit(Op.PUSH_CLOSURE, expr.line);
  this.chunk.emitI32(closureIdx, expr.line);
  break;
}

