  getGCStats(): GCStats[] {
    return this.gcStats;
  }

  /**
   * 현재 힙 크기
   */
  getHeapSize(): number {
    return this.gc.getHeapSize();
  }

  /**
   * Young 세대 크기
   */
  getYoungGenSize(): number {
    return this.gc.getYoungGenSize();
  }

  /**
   * Old 세대 크기
   */
  getOldGenSize(): number {
    return this.gc.getOldGenSize();
  }

  /**
   * GC 통계 초기화
   */
  clearGCStats(): void {
    this.gcStats = [];
    this.gc.clearStats();
  }
}

