  private readF64(actor: Actor): number {
    const buf = new ArrayBuffer(8);
    const bytes = new Uint8Array(buf);
    for (let i = 0; i < 8; i++) bytes[i] = this.chunk.code[actor.ip++];
    return new Float64Array(buf)[0];
