        case "-": return { tag: left.tag, val: lval - rval };
        case "*": return { tag: left.tag, val: lval * rval };
        case "/": return { tag: left.tag, val: lval / rval };
        case "%": return { tag: left.tag, val: lval % rval };
        case "==": return { tag: "bool", val: lval === rval };
        case "!=": return { tag: "bool", val: lval !== rval };
        case "<": return { tag: "bool", val: lval < rval };
        case ">": return { tag: "bool", val: lval > rval };
        case "<=": return { tag: "bool", val: lval <= rval };
        case ">=": return { tag: "bool", val: lval >= rval };
        default: return { tag: "void" };
      }
    }

    default:
      return { tag: "void" };
  }
}

