private parseBlock(): Stmt[] {
  const stmts: Stmt[] = [];
  while (!this.check(TokenType.RBRACE) && !this.isAtEnd()) {
    // Count errors before parsing
    const errorCountBefore = this.errors.length;

    // Parse statement - it may add errors but not throw
    stmts.push(this.parseStmt());

    // If errors were added and we're stuck, synchronize to recover
    if (this.errors.length > errorCountBefore && this.check(TokenType.RBRACE)) {
      break; // Stop here, let expect() handle RBRACE
    }
  }
  this.expect(TokenType.RBRACE, "expected '}'");
  return stmts;
}

